pug:
table.row.white-bg.b-system-text-82
    tr
        td.offset-by-one
            table.ten.columns
                tr
                    td.no-padding-bottom
                        p.title {{ text_1 }}
                        p.text {{ text_2 }}&nbsp;
                            a(href="{{ href_1 }}" target="_blank") {{ text_3 }}
                            | &nbsp;{{ text_4 }}

styl:
.white-bg.b-system-text-82 {  background:#fff  }
.b-system-text-82 .title {  color:#2473d7;font-size:24px;font-weight:500;line-height:32px;padding-top:30px;padding-bottom:25px  }
@media screen and (max-width:600px) {
  .b-system-text-82 .title {  padding-left:20px!important;padding-right:20px!important  }
}
.b-system-text-82 .text {  color:#5b6e88;font-size:16px;font-weight:400;line-height:24px;padding-bottom:20px  }
@media screen and (max-width:600px) {
  .b-system-text-82 .text {  padding-left:20px!important;padding-right:20px!important  }
}
.b-system-text-82 .text a {  color:#2473d7;text-decoration:underline  }
.b-system-text-82 .text.bold {  font-weight:700  }
